import numpy as np
from PIL import Image
im = np.array(Image.open('first_frame.png').convert('RGB'))
r,g,b = im[...,0].astype(int),im[...,1].astype(int),im[...,2].astype(int)
white=(r>150)&(g>150)&(b>150)
ys,xs=np.where(white)
print('box bbox', xs.min(),xs.max(),ys.min(),ys.max())
print('box color sample', im[15,160], im[30,140])
# table colors at various spots
for y,x in [(70,150),(100,50),(130,200),(60,200),(90,128)]:
    print('table',(y,x), im[y,x])
try:
    import cv2; print('cv2 ok', cv2.__version__)
except Exception as e: print('no cv2')
try:
    import scipy; print('scipy ok')
except Exception as e: print('no scipy')
# tube bbox: dark on left
dark=(r<30)&(g<30)&(b<30)
ys,xs=np.where(dark & (np.indices(r.shape)[1]<60))
print('tube dark bbox', xs.min(),xs.max(),ys.min(),ys.max())
EOF"
